import { expect, expectStatus, test, DOCUMENT_KINDS } from "../../fixtures";

// Note: e2e/AGENTS.md PW-0 says approval tests should not assert vendor status or audit events,
// but this scenario explicitly specifies both outcomes, so they are asserted here.
test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  // Act
  for (const kind of DOCUMENT_KINDS) {
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, { data: { decision: "approve" } }),
      200,
    );
  }

  // Assert
  await expect
    .poll(
      async () => (await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200)).status,
      { message: "vendor status after approving every extraction" },
    )
    .toBe("approved");
  await expect
    .poll(
      async () =>
        (
          await expectStatus<{ items: { action: string }[] }>(await reviewer.get(`/api/vendors/${vendor.id}/audit`), 200)
        ).items.map((e) => e.action),
      { message: "audit trail records vendor.approved" },
    )
    .toContain("vendor.approved");
});
